        values = [self._parse_number()]
        while self._text.startswith(",", self._pos):
            self._pos += 1
            values.append(self._parse_number())
        self._expect("]")
        return values

    def _parse_entry(self):
        self._expect('{"name":"')
        match = _STATE_NAME.match(self._text, self._pos)
        if match is None:
            self._fail()
