        self._expect('{"parameters":[')
        entries = [self._parse_entry()]
        while self._text.startswith(",", self._pos):
            self._pos += 1
            entries.append(self._parse_entry())
        self._expect("]}")
        if self._pos != len(self._text):
            self._fail()
        return entries


